local digits={}
for index,char in ("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):gmatch("()(.)") do digits[char:byte()]=index-1 end
local decoded={}
local function unpack_glyph(index)
 local cached=decoded[index];if cached then return cached end
 local value=packed[index];local parts={}
 for at=1,#value,4 do
  local a,b,c,d=value:byte(at,at+3)
  local n=digits[a]*262144+digits[b]*4096+(digits[c] or 0)*64+(digits[d] or 0)
  parts[#parts+1]=string.char(math.floor(n/65536)%256)
  if c~=61 then parts[#parts+1]=string.char(math.floor(n/256)%256) end
  if d~=61 then parts[#parts+1]=string.char(n%256) end
 end
 local bytes=table.concat(parts)
 local w,low,high,bearing=bytes:byte(1,4)
 if bearing>=128 then bearing=bearing-256 end
 local glyph={width=w,advance=(low+high*256)/64,bearing=bearing,r={}}
 for at=5,#bytes,4 do
  local a,b,c,d=bytes:byte(at,at+3);local n=a+b*256+c*65536+d*16777216
  glyph.r[#glyph.r+1]={n%64-16,math.floor(n/64)%64,math.floor(n/4096)%64+1,d,math.floor(n/262144)%64+1}
 end
 decoded[index]=glyph;return glyph
end
setmetatable(M.glyphs,{__index=function(_,char)
 local language=Text and Text.language() or "en"
 local chosen=regional[language]
 local index=chosen and chosen[char]
 if not index then
  for _,tag in ipairs({"ja","zh-hans","zh-hant","ko"}) do
   index=regional[tag][char];if index then break end
  end
 end
 return index and unpack_glyph(index) or nil
end})
M.regional_glyphs=regional
return M
